static uint64_t readUInt64Env(const char *Name, uint64_t DefaultValue) {
    if (const char *Value = std::getenv(Name)) {
        char *End = nullptr;
        unsigned long long Parsed = std::strtoull(Value, &End, 10);
        if (End != Value)
            return static_cast<uint64_t>(Parsed);
    }
    return DefaultValue;
}

static SmallVector<uint64_t, 8> readUInt64ListEnv(const char *Name) {
    SmallVector<uint64_t, 8> Values;
    if (const char *Raw = std::getenv(Name)) {
        StringRef Rest(Raw);
        while (!Rest.empty()) {
            auto Split = Rest.split(',');
            StringRef Item = Split.first.trim();
            if (!Item.empty()) {
                std::string ItemString = Item.str();
                char *End = nullptr;
                unsigned long long Parsed =
                    std::strtoull(ItemString.c_str(), &End, 10);
                if (End != ItemString.c_str() && Parsed != 0)
                    Values.push_back(static_cast<uint64_t>(Parsed));
            }
            Rest = Split.second;
        }
    }
    return Values;
}

static bool hasNonEmptyEnv(const char *Name) {
    const char *Value = std::getenv(Name);
    return Value && Value[0] != '\0';
}

