            for (Instruction *LoadI : CompactClusterLoadInstructions) {
                if (!LoadI)
                    continue;
                CompactClusterInstructions.insert(LoadI);
                CompactClusterBlocks.insert(LoadI->getParent());
            }
	            for (Instruction *ConsumerI : CompactClusterConsumerInstructions) {
	                if (!ConsumerI)
	                    continue;
	                CompactClusterInstructions.insert(ConsumerI);
	                CompactClusterBlocks.insert(ConsumerI->getParent());
	            }
	            Function *CompactClusterFunction = nullptr;
	            for (Instruction *ClusterI : CompactClusterInstructions) {
	                if (!ClusterI)
	                    continue;
	                CompactClusterFunction = ClusterI->getFunction();
	                break;
	            }
	            SmallVector<BasicBlock *, 32> BranchControlWorklist;
	            DenseSet<BasicBlock *> BranchControlVisited;
	            for (Instruction *ConsumerI : CompactClusterConsumerInstructions) {
	                if (!isa_and_nonnull<PHINode>(ConsumerI))
	                    continue;
	                BasicBlock *PhiBB = ConsumerI->getParent();
	                if (!PhiBB)
	                    continue;
	                for (BasicBlock *Pred : predecessors(PhiBB))
	                    BranchControlWorklist.push_back(Pred);
	            }
	            while (!BranchControlWorklist.empty()) {
	                BasicBlock *BB = BranchControlWorklist.pop_back_val();
	                if (!BB || !CompactClusterFunction ||
	                    BB->getParent() != CompactClusterFunction ||
	                    BranchControlVisited.count(BB) ||
	                    CompactClusterBlocks.count(BB))
	                    continue;
	                BranchControlVisited.insert(BB);
	                auto *BI = dyn_cast_or_null<BranchInst>(BB->getTerminator());
	                if (!BI)
	                    continue;
	                bool BranchFeedsCluster = false;
	                for (BasicBlock *Succ : successors(BB)) {
	                    if (CompactClusterBlocks.count(Succ)) {
	                        BranchFeedsCluster = true;
	                        break;
	                    }
	                }
	                if (!BranchFeedsCluster)
	                    continue;
	                CompactClusterBlocks.insert(BB);
	                for (Instruction &I : *BB) {
	                    if (I.isDebugOrPseudoInst())
	                        continue;
	                    CompactClusterInstructions.insert(&I);
	                }
	                for (BasicBlock *Pred : predecessors(BB))
	                    BranchControlWorklist.push_back(Pred);
	            }

	            DenseSet<Value *> ExplicitLiveInValues;
            DenseSet<Instruction *> ExplicitLiveOutValues;
