static bool isStdReferenceWrapperRefFunction(const Function &F) {
    StringRef Name = F.getName();
    return Name.starts_with("_ZSt3refI") &&
           Name.contains("St17reference_wrapper") &&
           F.getFunctionType()->getNumParams() >= 1 &&
           F.getReturnType()->isPointerTy() &&
           F.getFunctionType()->getParamType(0)->isPointerTy();
}

static bool isStdReferenceWrapperGetFunction(const Function &F) {
    StringRef Name = F.getName();
    return Name.starts_with("_ZNKSt17reference_wrapperI") &&
           Name.contains("E3getEv") &&
           F.getFunctionType()->getNumParams() >= 1 &&
           F.getReturnType()->isPointerTy() &&
           F.getFunctionType()->getParamType(0)->isPointerTy();
}

static Value *findStoredStdRefArgumentForWrapper(Value *WrapperObject,
                                                 Instruction *UsePoint,
                                                 DominatorTree &DT) {
    Value *WrapperBase = getUnderlyingObject(WrapperObject);
    Function *F = UsePoint->getFunction();
    Value *Best = nullptr;
    for (BasicBlock &BB : *F) {
        for (Instruction &I : BB) {
            auto *Store = dyn_cast<StoreInst>(&I);
            if (!Store)
                continue;
            if (!DT.dominates(Store, UsePoint))
                continue;
            if (getUnderlyingObject(Store->getPointerOperand()) != WrapperBase)
                continue;
            auto *Call = dyn_cast<CallBase>(Store->getValueOperand()->stripPointerCasts());
            if (!Call)
                continue;
            Function *Callee = Call->getCalledFunction();
            if (!Callee || !isStdReferenceWrapperRefFunction(*Callee))
                continue;
            Best = Call->getArgOperand(0);
        }
    }
    return Best;
}

static unsigned canonicalizeStdReferenceWrapperGetCalls(Module &M) {
    unsigned Replaced = 0;
    for (Function &F : M) {
        if (F.isDeclaration())
            continue;
        DominatorTree DT(F);
        SmallVector<CallBase *, 16> Calls;
        for (BasicBlock &BB : F) {
            for (Instruction &I : BB) {
                auto *Call = dyn_cast<CallBase>(&I);
                if (!Call)
                    continue;
                Function *Callee = Call->getCalledFunction();
                if (Callee && isStdReferenceWrapperGetFunction(*Callee))
                    Calls.push_back(Call);
            }
        }
        for (CallBase *Call : Calls) {
            Value *RootArg = findStoredStdRefArgumentForWrapper(Call->getArgOperand(0), Call, DT);
            if (!RootArg)
                continue;
            Call->replaceAllUsesWith(RootArg);
            Call->eraseFromParent();
            ++Replaced;
        }
    }
    return Replaced;
}

static bool isVlUnpackedSingleElementIndexFunction(const Function &F) {
    StringRef Name = F.getName();
    return (Name.starts_with("_ZN10VlUnpackedI") || Name.starts_with("_ZNK10VlUnpackedI")) &&
           Name.contains("Lm1EEixE") &&
           F.getFunctionType()->getNumParams() >= 2 &&
           F.getReturnType()->isPointerTy() &&
           F.getFunctionType()->getParamType(0)->isPointerTy();
}

static unsigned canonicalizeVlUnpackedSingleElementIndexCalls(Module &M) {
    unsigned Replaced = 0;
    for (Function &F : M) {
        if (F.isDeclaration())
            continue;
        SmallVector<CallBase *, 32> Calls;
        for (BasicBlock &BB : F) {
            for (Instruction &I : BB) {
                auto *Call = dyn_cast<CallBase>(&I);
                if (!Call)
                    continue;
                Function *Callee = Call->getCalledFunction();
                if (!Callee || !isVlUnpackedSingleElementIndexFunction(*Callee))
                    continue;
                Calls.push_back(Call);
            }
        }
        for (CallBase *Call : Calls) {
            Call->replaceAllUsesWith(Call->getArgOperand(0));
            Call->eraseFromParent();
            ++Replaced;
        }
    }
    return Replaced;
}

